use std::sync::{Arc, Mutex};

let customer = Arc::new(Mutex::new(Customer { id, name: "Ada".into() }));
let handle = Arc::clone(&customer);

assert!(Arc::ptr_eq(&customer, &handle));                 // same entity
assert_eq!(customer.lock().unwrap().id, handle.lock().unwrap().id);   // durable id
